-- Stage cue cards (admin "כרטיסיות הנחיה" page): one row per card, editable in
-- the admin UI. deck = 'mc' (event MC) | 'panel' (panel host). Text fields use a
-- light markup: **bold**, a line starting with "- " is a bullet, ___ is a blank.
CREATE TABLE IF NOT EXISTS cue_cards (
  id SERIAL PRIMARY KEY,
  deck TEXT NOT NULL,
  position INT NOT NULL DEFAULT 0,
  time_label TEXT,
  title TEXT,
  who TEXT,
  say TEXT,
  question TEXT,
  follow TEXT,
  notes TEXT,
  updated_at TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_cue_cards_deck ON cue_cards (deck, position);

